begin;
do $test$
declare player_id uuid:=gen_random_uuid();other_id uuid:=gen_random_uuid();tester_id uuid:=gen_random_uuid();anon_id uuid:=gen_random_uuid();staff_id uuid:=gen_random_uuid();admin_id uuid:=gen_random_uuid();actor uuid;
 original jsonb; changed jsonb; original_segments jsonb; bad jsonb; rev bigint; n integer; audits integer; level_xp bigint; target integer; money_before jsonb;
begin
 insert into auth.users(id,email) values(player_id,'wheel-player-'||player_id||'@example.invalid'),(other_id,'wheel-other-'||other_id||'@example.invalid'),(tester_id,'wheel-tester-'||tester_id||'@example.invalid'),(staff_id,'wheel-super-'||staff_id||'@example.invalid'),(admin_id,'wheel-admin-'||admin_id||'@example.invalid');
 update public.user_roles set role='superadmin' where user_id=staff_id;
 update public.user_roles set role='admin' where user_id=admin_id;
 update public.user_roles set role='tester' where user_id=tester_id;
 if (select count(*) from public.ig_vip_level_spins where user_id=player_id)<>1 then raise exception 'Signup did not earn exactly one level-1 spin';end if;
 select levels into original from public.ig_vip_catalog where id=1;
 select to_jsonb(w)-'experience_points'-'updated_at' into money_before from public.wallets w where w.user_id=player_id;
 foreach target in array array[11,12,24,25,34] loop
  level_xp:=(original->(target-1)->>'xp_required')::bigint;
  update public.wallets set experience_points=level_xp-1 where user_id=player_id;
  if (select count(*) from public.ig_vip_level_spins where user_id=player_id)<>target-1 then raise exception 'Spin earned before level threshold %',target;end if;
  update public.wallets set experience_points=level_xp where user_id=player_id;
  if (select count(*) from public.ig_vip_level_spins where user_id=player_id)<>target then raise exception 'Missing skipped level grants at %',target;end if;
 end loop;
 if (select count(*) from public.ig_vip_level_spins where user_id=player_id and stage=1)<>11 or
  (select count(*) from public.ig_vip_level_spins where user_id=player_id and stage=2)<>13 or
  (select count(*) from public.ig_vip_level_spins where user_id=player_id and stage=3)<>10 then raise exception 'Stage boundaries incorrect';end if;
 update public.wallets set experience_points=0 where user_id=player_id;
 update public.wallets set experience_points=level_xp where user_id=player_id;
 update public.wallets set experience_points=level_xp where user_id=player_id;
 if (select count(*) from public.ig_vip_level_spins where user_id=player_id)<>34 then raise exception 'Level replay duplicated spins';end if;
 if (select to_jsonb(w)-'experience_points'-'updated_at' from public.wallets w where w.user_id=player_id)<>money_before then raise exception 'Spin earning changed money';end if;
 update public.wallets set experience_points=500 where user_id=other_id;
 changed:=jsonb_set(original,'{1,xp_required}','100');
 update public.ig_vip_catalog set levels=changed where id=1;
 update public.wallets set experience_points=501 where user_id=other_id;
 if (select count(*) from public.ig_vip_level_spins where user_id=other_id)<>1 then raise exception 'Catalog edit awarded an unearned spin';end if;
 update public.ig_vip_catalog set levels=original where id=1;
 update public.wallets set experience_points=1000 where user_id=other_id;
 if (select count(*) from public.ig_vip_level_spins where user_id=other_id)<>2 then raise exception 'Fresh threshold crossing did not earn spin';end if;
 update public.wallets set experience_points=1000 where user_id=tester_id;
 if (select count(*) from public.ig_vip_level_spins where user_id=tester_id)<>1 then raise exception 'Tester earned new spin';end if;
 insert into auth.users(id,email,is_anonymous) values(anon_id,'wheel-anon-'||anon_id||'@example.invalid',true);
 if exists(select 1 from public.ig_vip_level_spins where user_id=anon_id) then raise exception 'Anonymous signup earned a spin';end if;
 update auth.users set is_anonymous=false where id=anon_id;
 if (select count(*) from public.ig_vip_level_spins where user_id=anon_id)<>1 then raise exception 'Registered account missed starter spin';end if;
 perform set_config('request.jwt.claim.sub',player_id::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',player_id,'role','authenticated','is_anonymous',false,'user_metadata',jsonb_build_object('role','superadmin'))::text,true);
 set local role authenticated;
 if (select count(*) from public.ig_vip_level_spins)<>34 then raise exception 'Other accounts spins visible';end if;
 if exists(select 1 from public.ig_vip_wheel_settings) then raise exception 'Player read private wheel drafts';end if;
 begin delete from public.ig_vip_level_spins where user_id=player_id;raise exception 'Client consumed spins';exception when insufficient_privilege then null;end;
 begin insert into public.ig_vip_level_spins(user_id,level,level_name,required_xp,earned_xp,catalog_revision,source) values(player_id,1,'Fake',0,0,1,'signup');raise exception 'Client forged spin';exception when insufficient_privilege then null;end;
 begin perform internal.grant_vip_level_spins(player_id,-1,1000,'signup');raise exception 'Client invoked grant helper';exception when insufficient_privilege then null;end;
 reset role;
 select s.segments,s.revision into original_segments,rev from public.ig_vip_wheel_settings s where stage=1;
 select count(*) into audits from internal.vip_wheel_settings_history;
 changed:=jsonb_set(original_segments,'{0,amount}','"9999999999999999.12345678"');
 foreach actor in array array[player_id,tester_id,admin_id] loop
  perform set_config('request.jwt.claim.sub',actor::text,true);
  perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated','is_anonymous',false,'user_metadata',jsonb_build_object('role','superadmin'))::text,true);
  set local role authenticated;
  update public.ig_vip_wheel_settings set segments=changed where stage=1;
  get diagnostics n=row_count;if n<>0 then raise exception 'Non-superadmin changed wheel';end if;
  reset role;
 end loop;
 perform set_config('request.jwt.claim.sub',staff_id::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',staff_id,'role','authenticated','is_anonymous',false)::text,true);
 set local role authenticated;
 if (select count(stage) from public.ig_vip_wheel_settings)<>3 then raise exception 'Admin cannot read all wheels';end if;
 update public.ig_vip_wheel_settings set segments=changed where stage=1 and revision=rev;
 if (select revision from public.ig_vip_wheel_settings where stage=1)<>rev+1 then raise exception 'Wheel revision did not advance';end if;
 if (select s.segments->0->>'amount' from public.ig_vip_wheel_settings s where stage=1)<>'9999999999999999.12345678' then raise exception 'Decimal reward amount rounded';end if;
 update public.ig_vip_wheel_settings set segments=original_segments where stage=1 and revision=rev;
 get diagnostics n=row_count;if n<>0 then raise exception 'Stale wheel overwrite accepted';end if;
 foreach bad in array array['{}'::jsonb,'[]'::jsonb,jsonb_set(original_segments,'{0,amount}','"1e3"'),jsonb_set(original_segments,'{0,amount}','"-1"'),jsonb_set(original_segments,'{0,amount}','"1.123456789"'),jsonb_set(original_segments,'{0,weight}','0.5'),jsonb_set(original_segments,'{0,weight}','-1'),jsonb_set(original_segments,'{0,weight}','10001'),jsonb_set(original_segments,'{0,reward}','""'),jsonb_set(original_segments,'{0,slot}','2'),jsonb_set(original_segments,'{0,enabled}','true')] loop
  begin update public.ig_vip_wheel_settings set segments=bad where stage=1;raise exception 'Invalid wheel configuration accepted';exception when check_violation then null;end;
 end loop;
 begin update public.ig_vip_wheel_settings set revision=99 where stage=1;raise exception 'Wheel revision spoofed';exception when insufficient_privilege then null;end;
 begin perform changed_by from internal.vip_wheel_settings_history;raise exception 'Private wheel audit exposed';exception when insufficient_privilege then null;end;
 reset role;
 if (select count(*) from internal.vip_wheel_settings_history)<>audits+1 or (select changed_by from internal.vip_wheel_settings_history where stage=1 and revision=rev+1)<>staff_id then raise exception 'Wheel audit not atomic';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',staff_id,'role','service_role')::text,true);
 update public.profiles set is_excluded=true where id=staff_id;
 update public.wallets set experience_points=1000 where user_id=staff_id;
 if (select count(*) from public.ig_vip_level_spins where user_id=staff_id)<>1 then raise exception 'Excluded account earned spin';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',staff_id,'role','authenticated','is_anonymous',false)::text,true);
 set local role authenticated;
 if exists(select 1 from public.ig_vip_level_spins) then raise exception 'Excluded account read spins';end if;
 update public.ig_vip_wheel_settings set segments=changed where stage=1;
 get diagnostics n=row_count;if n<>0 then raise exception 'Excluded superadmin changed wheel';end if;
 reset role;
end $test$;
select 'PASS: one spin per level, 11/12/24/25/34 boundaries, jump/replay protection, no catalog-only grants, signup registration, owner RLS, tester/exclusion controls, no money movement, superadmin draft edits, exact amounts and atomic audit' as result;
rollback;
